flowchart TD
  A["Un número en inglés"] --> B{"¿Su última palabra es one, two o three?"}
  B -->|"one"| C["first · 1st · twenty-first"]
  B -->|"two"| D["second · 2nd · thirty-second"]
  B -->|"three"| E["third · 3rd · forty-third"]
  B -->|"no"| F{"¿Termina en -ty?"}
  F -->|"sí"| G["y → ie + th · twentieth, fiftieth"]
  F -->|"no"| H{"¿Es five, eight, nine o twelve?"}
  H -->|"sí"| I["fifth · eighth · ninth · twelfth"]
  H -->|"no"| J["+ th · fourth, sixth, seventeenth, hundredth"]

flowchart TD
  A["Quiero decir «hacer»"] --> B{"¿Es una combinación fija? (a mistake, homework, the bed…)"}
  B -->|"sí"| C["Apréndela de memoria: mira la tabla de abajo"]
  B -->|"no"| D{"¿Creo, fabrico o preparo algo que antes no existía?"}
  D -->|"sí"| E["MAKE · make a table, make bread, make a cake"]
  D -->|"no"| F{"¿Realizo una actividad, un trabajo o una tarea?"}
  F -->|"sí"| G["DO · do the work, do the shopping, do exercise"]
  F -->|"no, es algo sin nombre (eso, algo, nada)"| H["DO · do that, do something, do nothing"]

flowchart TD
  A["Verbo + ed"] --> B{"¿El verbo termina en sonido t o d?"}
  B -->|"sí"| C["/ɪd/ · una sílaba más · rested, needed, planted, painted"]
  B -->|"no"| D{"¿Termina en sonido sordo? p, k, f, s, sh, ch"}
  D -->|"sí"| E["/t/ · looked, pushed, laughed, placed, kicked"]
  D -->|"no"| F["/d/ · named, moved, cried, cleaned, smiled"]
